// Resuming a run after a crash: which steps still need to run (DESIGN.md §"Recovery").
// `events` is the append-only step log. Every step is idempotent, so the planner only has to decide what is safe
// to run again — it must never hand back a step that already finished.

/** One step of a run's plan. */
export interface PlanStep {
  key: string;
  dependsOn: string[];
}

export type StepStatus = "started" | "done" | "failed";

/** One line of the step log. */
export interface StepEvent {
  key: string;
  status: StepStatus;
}

/** A step that has failed this many times is excluded; so are the steps that depend on it. */
export const MAX_FAILURES = 3;

interface StepState {
  /** The status of the last event for the step, or null if it never ran. */
  status: StepStatus | null;
  failures: number;
}

/** Folds the log into one state per step. The last event wins, so a re-run that crashes reads as unfinished. */
function states(events: StepEvent[]): Map<string, StepState> {
  const byKey = new Map<string, StepState>();
  for (const e of events) {
    const s = byKey.get(e.key) ?? { status: null, failures: 0 };
    s.status = e.status;
    if (e.status === "failed") s.failures++;
    byKey.set(e.key, s);
  }
  return byKey;
}

/**
 * The keys to run next: in plan order, the steps whose dependencies are all done and which are not done
 * themselves. A step that started but did not finish is returned again, and so is a failed step — until it has
 * failed `MAX_FAILURES` times, after which it and its dependents are left out.
 */
export function nextSteps(plan: { steps: PlanStep[] }, events: StepEvent[]): string[] {
  const state = states(events);
  // A step with too many failures never counts as done, so its dependents can never become ready either.
  const excluded = new Set<string>();
  const done = new Set<string>();
  for (const [key, s] of state) {
    if (s.failures >= MAX_FAILURES) excluded.add(key);
    else if (s.status === "done") done.add(key);
  }

  const ready: string[] = [];
  for (const step of plan.steps) {
    if (done.has(step.key) || excluded.has(step.key)) continue;
    // A dependency that is missing from the plan, unfinished or excluded is not done: the step is not ready.
    if (step.dependsOn.every((dep) => done.has(dep))) ready.push(step.key);
  }
  return ready;
}

import { describe, expect, test } from "bun:test";
import { MAX_FAILURES, nextSteps, type PlanStep, type StepEvent } from "../src/agent/resume.ts";

const plan = (...steps: [string, ...string[]][]) => ({
  steps: steps.map(([key, ...dependsOn]) => ({ key, dependsOn }) as PlanStep),
});
const events = (...es: [string, StepEvent["status"]][]): StepEvent[] =>
  es.map(([key, status]) => ({ key, status }));

describe("nextSteps", () => {
  test("an empty log returns the roots in plan order, not their dependents", () => {
    const p = plan(["a"], ["b", "a"], ["c", "b"], ["d"]);
    expect(nextSteps(p, [])).toEqual(["a", "d"]);
  });

  test("finished steps are never returned twice", () => {
    const p = plan(["a"], ["b", "a"], ["c", "a"]);
    expect(nextSteps(p, events(["a", "done"], ["b", "done"]))).toEqual(["c"]);
    expect(nextSteps(p, events(["a", "done"], ["b", "done"], ["c", "done"]))).toEqual([]);
  });

  test("a step whose dependencies are not all done waits", () => {
    const p = plan(["a"], ["b"], ["c", "a", "b"]);
    expect(nextSteps(p, events(["a", "done"]))).toEqual(["b"]);
    expect(nextSteps(p, events(["a", "done"], ["b", "done"]))).toEqual(["c"]);
  });

  test("a step that started but did not finish is returned again", () => {
    const p = plan(["a"], ["b", "a"]);
    expect(nextSteps(p, events(["a", "started"]))).toEqual(["a"]);
  });

  test("a step that finished and was started again is returned again", () => {
    const p = plan(["a"], ["b", "a"]);
    expect(nextSteps(p, events(["a", "done"], ["a", "started"]))).toEqual(["a"]);
  });

  test("a failed step is returned again until it has failed MAX_FAILURES times", () => {
    const p = plan(["a"], ["b", "a"]);
    for (let n = 1; n < MAX_FAILURES; n++) {
      expect(nextSteps(p, events(...Array.from({ length: n }, () => ["a", "failed"] as [string, "failed"])))).toEqual([
        "a",
      ]);
    }
  });

  test(`at ${MAX_FAILURES} failures the step and its dependents are excluded`, () => {
    const p = plan(["a"], ["b", "a"], ["c", "b"], ["d"]);
    const failed = events(...Array.from({ length: MAX_FAILURES }, () => ["a", "failed"] as [string, "failed"]));
    expect(nextSteps(p, [...failed, ...events(["d", "done"])])).toEqual([]);
    expect(nextSteps(p, failed)).toEqual([]);
  });

  test("a dependent is not returned when a dependency is missing from the plan", () => {
    const p = plan(["a", "ghost"], ["b", "a"]);
    expect(nextSteps(p, [])).toEqual([]);
  });

  test("events for steps outside the plan are ignored", () => {
    const p = plan(["a"]);
    expect(nextSteps(p, events(["elsewhere", "done"]))).toEqual(["a"]);
  });

  test("the result follows plan order, not the order the events arrived in", () => {
    const p = plan(["a"], ["b"], ["c", "a"]);
    expect(nextSteps(p, events(["b", "started"], ["a", "done"]))).toEqual(["b", "c"]);
  });

  test("resuming a chain from a snapshot of the log only replays the unfinished tail", () => {
    const p = plan(["a"], ["b", "a"], ["c", "b"], ["d", "b"]);
    // a and b finished, c crashed mid-run, d never started.
    const log = events(["a", "started"], ["a", "done"], ["b", "started"], ["b", "done"], ["c", "started"]);
    expect(nextSteps(p, log)).toEqual(["c", "d"]);
  });
});

